mapper.insert:
INSERT INTO ai_conversations (
    user_id,
    scope,
    status
) VALUES (
    #{userId},
    #{scope},
    #{status}
)

mapper.select:
SELECT *
FROM ai_conversations
WHERE conversation_id = #{conversationId}
  AND user_id         = #{userId}

SELECT *
FROM ai_conversations
WHERE conversation_id = #{conversationId}
  AND user_id         = #{userId}
FOR UPDATE

mapper.update:
UPDATE ai_conversations
SET updated_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND user_id         = #{userId}

UPDATE ai_conversations
SET active_request_message_id = #{requestMessageId},
    active_request_started_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND user_id         = #{userId}

UPDATE ai_conversations
SET active_request_message_id = NULL,
    active_request_started_at = NULL
WHERE conversation_id           = #{conversationId}
  AND user_id                   = #{userId}
  AND active_request_message_id = #{requestMessageId}
